def smallestWithDigitSquareSum(target):
    mask = (1 << (target + 1)) - 1
    reach = [1]
    L = None
    for r in range(1, target + 1):
        cur = 0
        prev = reach[-1]
        for d in range(1, 10):
            cur |= prev << (d * d)
        reach.append(cur & mask)
        if (cur >> target) & 1:
            L = r
            break
    digits = []
    rem = target
    for pos in range(L):
        left = L - pos - 1
        for d in range(1, 10):
            if d * d <= rem and (reach[left] >> (rem - d * d)) & 1:
                digits.append(str(d))
                rem -= d * d
                break
    return "".join(digits)
